import { useState } from 'react';
import { Link } from 'react-router-dom';
import Layout from '../components/Layout';
import { performancePages } from '../websitePerformanceContent';
import { useSEO, breadcrumbSchema, absoluteUrl } from '../seo';

const PSI_ENDPOINT = 'https://www.googleapis.com/pagespeedonline/v5/runPagespeed';

function normalizeUrl(value) {
  const trimmed = value.trim();
  if (!trimmed) return '';
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
}

function scoreLabel(score) {
  if (score >= 90) return 'Excellent';
  if (score >= 50) return 'Needs improvement';
  return 'Poor';
}

function formatMs(value) {
  if (!Number.isFinite(value)) return '—';
  if (value >= 1000) return `${(value / 1000).toFixed(1)} s`;
  return `${Math.round(value)} ms`;
}

function formatBytes(value) {
  if (!Number.isFinite(value)) return '—';
  if (value >= 1024 * 1024) return `${(value / (1024 * 1024)).toFixed(2)} MB`;
  if (value >= 1024) return `${Math.round(value / 1024)} KB`;
  return `${Math.round(value)} B`;
}

function getAuditNumeric(audits, key) {
  const value = audits?.[key]?.numericValue;
  return Number.isFinite(value) ? value : null;
}

export default function WebsitePerformance() {
  const description = 'Learn Core Web Vitals, PageSpeed Insights, GTmetrix and website speed optimization with simple Speed Pings guides.';
  const [url, setUrl] = useState('');
  const [strategy, setStrategy] = useState('mobile');
  const [checking, setChecking] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);

  useSEO({
    title: 'Website Performance Guides & Website Loading Speed Test | Speed Pings',
    description: 'Check website loading speed with PageSpeed Insights data and learn Core Web Vitals, GTmetrix, mobile speed and website optimization with Speed Pings guides.',
    path: '/website-performance',
    schemas: [
      breadcrumbSchema([{ name: 'Home', path: '/' }, { name: 'Website Performance', path: '/website-performance' }]),
      {
        '@context': 'https://schema.org',
        '@type': 'WebApplication',
        name: 'Website Loading Speed Checker',
        applicationCategory: 'DeveloperApplication',
        operatingSystem: 'Any',
        url: absoluteUrl('/website-performance'),
        description: 'Free website loading speed checker using Google PageSpeed Insights performance data.'
      },
      {
        '@context': 'https://schema.org',
        '@type': 'CollectionPage',
        name: 'Website Performance Guides',
        description,
        url: absoluteUrl('/website-performance'),
        mainEntity: performancePages.map((page) => ({
          '@type': 'Article',
          headline: page.title,
          description: page.description,
          url: absoluteUrl(`/website-performance/${page.slug}`)
        }))
      }
    ]
  });

  const checkWebsiteSpeed = async (event) => {
    event.preventDefault();

    const finalUrl = normalizeUrl(url);
    if (!finalUrl) {
      setError('Please enter a website URL.');
      return;
    }

    try {
      new URL(finalUrl);
    } catch {
      setError('Please enter a valid URL, for example speedpings.com');
      return;
    }

    try {
      setChecking(true);
      setError('');
      setResult(null);

      const params = new URLSearchParams({
        url: finalUrl,
        strategy,
        category: 'performance'
      });

      const response = await fetch(`${PSI_ENDPOINT}?${params.toString()}`);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data?.error?.message || 'Unable to check this website right now.');
      }

      const lighthouse = data.lighthouseResult;
      const audits = lighthouse?.audits || {};
      const categories = lighthouse?.categories || {};
      const score = Math.round((categories.performance?.score || 0) * 100);
      const resources = audits['resource-summary']?.details?.items || [];
      const totalResource = resources.find((item) => item.resourceType === 'total');

      setResult({
        testedUrl: lighthouse?.finalDisplayedUrl || finalUrl,
        fetchedAt: lighthouse?.fetchTime,
        score,
        label: scoreLabel(score),
        fcp: getAuditNumeric(audits, 'first-contentful-paint'),
        lcp: getAuditNumeric(audits, 'largest-contentful-paint'),
        tbt: getAuditNumeric(audits, 'total-blocking-time'),
        cls: audits['cumulative-layout-shift']?.numericValue,
        speedIndex: getAuditNumeric(audits, 'speed-index'),
        pageSize: totalResource?.transferSize,
        requests: totalResource?.requestCount,
        strategy
      });
    } catch (err) {
      setError(err.message || 'Website speed check failed. Please try again.');
    } finally {
      setChecking(false);
    }
  };

  return (
    <Layout>
      <main className="page-hero">
        <section className="page-title">
          <span className="hero-kicker">Website Performance</span>
          <h1>Website Performance, Core Web Vitals and Page Speed Guides</h1>
          <p>
            Check a website loading speed report, then learn how to improve Core Web Vitals, Google PageSpeed
            Insights scores, GTmetrix reports, mobile website speed and user experience.
          </p>
        </section>

        <section className="legal-container website-speed-tool" aria-labelledby="website-speed-checker-title">
          <div className="tool-heading-row">
            <div>
              <span className="hero-kicker">Free Tool</span>
              <h2 id="website-speed-checker-title">Website Loading Speed Checker</h2>
              <p>
                Enter any public website URL to check loading speed using Google PageSpeed Insights performance data.
              </p>
            </div>
          </div>

          <form className="website-speed-form" onSubmit={checkWebsiteSpeed}>
            <input
              type="text"
              value={url}
              onChange={(event) => setUrl(event.target.value)}
              placeholder="Enter website URL, e.g. speedpings.com"
              aria-label="Website URL"
            />
            <select value={strategy} onChange={(event) => setStrategy(event.target.value)} aria-label="Test device">
              <option value="mobile">Mobile</option>
              <option value="desktop">Desktop</option>
            </select>
            <button type="submit" className="run-btn" disabled={checking}>
              {checking ? 'Checking...' : 'Check Speed'}
            </button>
          </form>

          {error && <p className="form-note error-note">{error}</p>}

          {result && (
            <div className="website-speed-results">
              <div className="performance-score-card">
                <span>Performance Score</span>
                <strong>{result.score}</strong>
                <p>{result.label} · {result.strategy}</p>
              </div>
              <div className="performance-metrics-grid">
                <div><span>First Contentful Paint</span><strong>{formatMs(result.fcp)}</strong></div>
                <div><span>Largest Contentful Paint</span><strong>{formatMs(result.lcp)}</strong></div>
                <div><span>Total Blocking Time</span><strong>{formatMs(result.tbt)}</strong></div>
                <div><span>Cumulative Layout Shift</span><strong>{Number.isFinite(result.cls) ? result.cls.toFixed(3) : '—'}</strong></div>
                <div><span>Speed Index</span><strong>{formatMs(result.speedIndex)}</strong></div>
                <div><span>Page Size</span><strong>{formatBytes(result.pageSize)}</strong></div>
                <div><span>Requests</span><strong>{Number.isFinite(result.requests) ? result.requests : '—'}</strong></div>
              </div>
              <p className="tested-url">Tested URL: {result.testedUrl}</p>
            </div>
          )}
        </section>

        <section className="legal-container seo-section">
          <h2>Website Speed Learning Center</h2>
          <p>
            This section is for website owners, developers, bloggers, SEO professionals and marketers who want
            to understand page speed, Core Web Vitals, website speed test reports and practical optimization steps.
            For checking your internet connection speed, use the Speed Pings home page.
          </p>
        </section>

        <section className="article-grid">
          {performancePages.map((page) => (
            <Link className="article-card" key={page.slug} to={`/website-performance/${page.slug}`}>
              <div className="article-visual performance-icon" aria-hidden="true">{page.icon}</div>
              <h2>{page.title}</h2>
              <p>{page.description}</p>
              <strong>Read guide →</strong>
            </Link>
          ))}
        </section>
      </main>
    </Layout>
  );
}
